const page=await figma.getNodeByIdAsync('194:38164');await figma.setCurrentPageAsync(page);const roots=page.children.filter(n=>n.type==='FRAME'),mapping={};for(const f of roots)if(/^[A-Z]\d\d ·/.test(f.name))mapping[f.name.slice(0,3)+(f.width===390?'m':'d')]=f;
const mutated=[],missing=[],self=[],links=[];for(const id of FRAMES){const f=await figma.getNodeByIdAsync(id),suffix=f.width===390?'m':'d';for(const n of f.findAll(n=>/^GO [A-Z]\d\d ·/.test(n.name))){const key=n.name.slice(3,6)+suffix,dest=mapping[key];if(!dest){missing.push({frame:f.id,node:n.id,name:n.name});continue;}if(dest.id===f.id){await n.setReactionsAsync([]);self.push(n.id);}else{await n.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest.id,navigation:'NAVIGATE',transition:null,preserveScrollPosition:['V02','V22','V23','V24'].includes(f.name.slice(0,3))&&['Weltaktien','Nasdaq 100'].includes(n.name.slice(9))}]}]);links.push({node:n.id,target:dest.id});}mutated.push(n.id);}}
return{createdNodeIds:[],mutatedNodeIds:mutated,missing,selfTargets:self,linked:links.length,targetCounts:links.reduce((a,l)=>(a[l.target]=(a[l.target]||0)+1,a),{})};
